import{_ as o,C as l,o as e,c as t,j as i,a as n,E as r,a3 as d}from"./chunks/framework.D4-ViStF.js";const D=JSON.parse('{"title":"坐忘论","description":"唐代司马承祯的修真名篇，以坐忘收心为入口，七阶次第归道；与《天隐子》相表里。","frontmatter":{"title":"坐忘论","description":"唐代司马承祯的修真名篇，以坐忘收心为入口，七阶次第归道；与《天隐子》相表里。","category":"guide","aliases":["坐忘论","zuowang lun","坐忘论全文","司马承祯坐忘论"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/index.md","filePath":"daoism/daoist-classics/zuowang-lun/index.md","lastUpdated":1789714390000}'),c={name:"daoism/daoist-classics/zuowang-lun/index.md"};function u(h,a,m,p,f,g){const s=l("DaoReadingPrelude");return e(),t("div",null,[a[0]||(a[0]=i("h1",{id:"坐忘论",tabindex:"-1"},[n("坐忘论 "),i("a",{class:"header-anchor",href:"#坐忘论","aria-label":'Permalink to "坐忘论"'},"​")],-1)),r(s,{title:"先看坐忘如何收心归道",summary:"坐忘论不是谈玄说妙的空论，而是从「敬信」到「得道」的七步实修路径。它不从盘坐姿势开始，而从一场价值反省开始：人珍惜生命，却不知生命依道而全。",points:[{label:"先通",text:"七篇顺序不是随意排的——敬信是根，得道是果。"},{label:"再体",text:"收心、真观、泰定三步是核心功夫。"},{label:"后归",text:"全篇终点不是神异，而是身心与道合一。"}],hint:"第一次读，建议先通读《全书引读》立起地图，再从《序说》开始逐篇细看。"}),a[1]||(a[1]=d('<h2 id="篇目" tabindex="-1">篇目 <a class="header-anchor" href="#篇目" aria-label="Permalink to &quot;篇目&quot;">​</a></h2><p>全书七篇，另附《坐忘枢翼》一篇总诀；其引文出处集中收在「引经据典」一页。</p><ul><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/preface">序说</a> —— 人贵其生、生贵其道；痛陈倒置之弊，标出七条阶次</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-01">敬信一</a> —— 信为道根、敬为德蒂；先解决「为什么要修」</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-02">断缘二</a> —— 断机心、名利与攀附之缘</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-03">收心三</a> —— 全书最长一篇：收心离境，息乱而不灭照</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-04">简事四</a> —— 分辨必要与非必要、分内与分外</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-05">真观五</a> —— 观衣食、色欲、善恶、贫病、生死之本</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-06">泰定六</a> —— 无心于定而无所不定；定慧交养</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-07">得道七</a> —— 含光藏辉，形神合同，与道冥一</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-08">坐忘枢翼</a> —— 三戒与调心总诀；心有五时，身有七候</li></ul><p>两页专收：</p><ul><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/guide">全书引读</a> —— 结构地图、七篇逻辑、思想来源、与《天隐子》的对应、路线图与常见误读</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">引经据典</a> —— 全书二十七条引文的出处、原典语境，以及司马承祯如何转化它们</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读<a href="/Dao/daoism/daoist-classics/zuowang-lun/guide">《全书引读》</a>，把七篇的地图立起来——知道每一步在解决什么问题；</li><li>再从<a href="/Dao/daoism/daoist-classics/zuowang-lun/preface">《序说》</a>起，按 <strong>序说 → 敬信 → 断缘 → 收心 → 简事 → 真观 → 泰定 → 得道 → 枢翼</strong> 逐篇读；</li><li>遇到「经云」而不确定出处的，翻<a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">《引经据典》</a>对照；</li><li>读到与《天隐子》相通之处，回<a href="/Dao/daoism/daoist-classics/tianyinzi">天隐子</a>对照阅读。</li></ol><h2 id="与《天隐子》的关系" tabindex="-1">与《天隐子》的关系 <a class="header-anchor" href="#与《天隐子》的关系" aria-label="Permalink to &quot;与《天隐子》的关系&quot;">​</a></h2><p>两书传统上都与司马承祯相关，思想互相呼应。最简明的分法是：</p><blockquote><p><strong>《天隐子》给出路线图，《坐忘论》详细解释行路时会遇到什么困难。</strong></p></blockquote><ul><li>《天隐子》五渐：斋戒 → 安处 → 存想 → 坐忘 → 神解</li><li>《坐忘论》七阶：敬信 → 断缘 → 收心 → 简事 → 真观 → 泰定 → 得道</li></ul><p>逐篇对应表与关键概念的深化说明，见<a href="/Dao/daoism/daoist-classics/zuowang-lun/guide#八与天隐子的对应与差异">《全书引读》· 与《天隐子》的对应与差异</a>。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《坐忘论》，唐·司马承祯撰。</li><li>《云笈七签》收录版本。</li><li>相关篇目：<a href="/Dao/daoism/daoist-classics/tianyinzi">《天隐子》</a>、<a href="/Dao/daoism/zhuang-zi/chapter-06">《庄子·大宗师》</a>（「坐忘」出处）。</li></ul>',14))])}const _=o(c,[["render",u]]);export{D as __pageData,_ as default};
